def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ""

    idx_map = {c: i for i, c in enumerate(inorder)}

    def helper(i_start: int, i_end: int, p_start: int, p_end: int) -> str:
        if i_start >= i_end or p_start >= p_end:
            return ""
        root = postorder[p_end - 1]
        i_root = idx_map[root]
        left_size = i_root - i_start
        # left subtree
        left_pre = helper(i_start, i_root, p_start, p_start + left_size)
        # right subtree
        right_pre = helper(i_root + 1, i_end, p_start + left_size, p_end - 1)
        return root + left_pre + right_pre

    return helper(0, len(inorder), 0, len(postorder))

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Performs a breadth‑first search to transform string A into string B using
    the supplied transformation rules.  Each element of ``rules`` is a tuple
    (src, dst) meaning that any occurrence of ``src`` in the current string
    may be replaced by ``dst`` in a single transformation step.

    If B can be obtained in 10 or fewer transformations, the minimum number of
    steps is returned; otherwise the string ``"NO ANSWER!"`` is returned.
    """
    if A == B:
        return 0

    visited = {A}
    queue = [(A, 0)]

    while queue:
        current, steps = queue.pop(0)

        # We are only interested in expansions that keep the depth within 10
        if steps >= 10:
            continue

        for src, dst in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + dst + current[idx + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    if new_str == B:
                        return steps + 1
                    queue.append((new_str, steps + 1))
                start = idx + 1

    return "NO ANSWER!"

def string_transformation(A: str, B: str, rules: List[Tuple[str, str]]) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.

    Parameters:
