def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Parameters:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    # Build a mapping from digit to list of possible replacements
    mapping = {}
    for x, y in rules:
        mapping.setdefault(str(x), set()).add(str(y))

    start = str(n)
    visited = {int(start)}
    queue = [start]

    while queue:
        current_str = queue.pop(0)
        for idx, ch in enumerate(current_str):
            if ch in mapping:
                for new_digit in mapping[ch]:
                    new_num_str = current_str[:idx] + new_digit + current_str[idx + 1 :]
                    new_num = int(new_num_str)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    scenario = scenario.upper()
    days_of_week = {d.upper() for d in days_of_week}

    def clean(s):
        return s.replace('.', '').replace(',', '').strip().upper()

    def is_truthful(stmt: str, speaker: str) -> bool:
        s_clean = clean(stmt)
        # ignore if statement refers to a day of week
        words = set(s_clean.split())
        if words & days_of_week:
            return True  # skip day statements: treat as truth for consistency

        # pattern: I am guilty / I am not guilty
        if s_clean.startswith('I AM '):
            if 'NOT GUILTY' in s_clean:
                return speaker.upper() != scenario
            else:
                return speaker.upper() == scenario

        # pattern: NAME is guilty / NAME is not guilty
        if ' IS GUILTY' in s_clean:
            name = s_clean.split(' IS GUILTY')[0].strip()
            return name == scenario

        if ' IS NOT GUILTY' in s_clean:
            name = s_clean.split(' IS NOT GUILTY')[0].strip()
            return name != scenario

        # If statement is unrelated or cannot be parsed, assume it's true
        return True

    for speaker, stmts in statements.items():
        speaker_upper = speaker.upper()
        for stmt in stmts:
            truth = is_truthful(stmt, speaker_upper)
            if speaker_upper in liar_count:
                if truth:  # liar's statement can't be true
                    return False
            else:
                if not truth:  # non-liar's statement can't be false
                    return False
