def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    Disregards any statements about the day of the week.
    """
    def is_day_statement(stmt: str) -> bool:
        lower = stmt.lower()
        for day in days_of_week:
            if day.lower() in lower:
                return True
        return False

    def eval_statement(stmt: str, speaker: str) -> bool:
        """
        Returns True if the statement is logically true given the scenario, False otherwise.
        Supports only simple guilty/not guilty statements of the form:
          - "I am guilty./I am not guilty."
          - "<NAME> is guilty./<NAME> is not guilty."
        """
        stmt_clean = stmt.strip().rstrip('.')
        lower = stmt_clean.lower()
        if lower.startswith("i am guilty"):
            return scenario.lower() == speaker.lower()
        if lower.startswith("i am not guilty"):
            return scenario.lower() != speaker.lower()
        # Check for "<name> is guilty" or "<name> is not guilty"
        if " is guilty" in lower:
            name_part = stmt_clean.split(" is guilty")[0].strip()
            return scenario.lower() == name_part.lower()
        if " is not guilty" in lower:
            name_part = stmt_clean.split(" is not guilty")[0].strip()
            return scenario.lower() != name_part.lower()
        # If statement format not recognized, treat as neutral (no impact)
        return None

    for speaker, speaker_statements in statements.items():
        for stmt in speaker_statements:
            # ignore day-of-week statements
            if is_day_statement(stmt):
                continue
            truth_value = eval_statement(stmt, speaker)
            # If the statement format is unrecognized, skip evaluation
            if truth_value is None:
                continue
            if speaker in liar_count:
                # liars must be lying: statement should be false
                if truth_value:
                    return False
            else:
                # truthers must tell truth: statement must be true
                if not truth_value:
                    return False
    return True

