    """Return the minimum remaining space in a box of size V after packing a subset of n items."""
    # Limit the list to the first n items
    volumes = volumes[:n]
    # DP array: dp[c] is True if capacity c can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    best = 0
    for vol in volumes:
        if vol > V:
            continue
        # Go backwards to avoid reuse of the same item
        for c in range(V, vol - 1, -1):
            if dp[c - vol]:
                dp[c] = True
                if c > best:
                    best = c
    return V - best

