    mod = 10**6 + 7
    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1
    for limit in a[:n]:
        # Prefix sums of dp_prev
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for k in range(1, m + 1):
            prefix[k] = (prefix[k - 1] + dp_prev[k]) % mod
        # Compute dp for current type
        dp_curr = [0] * (m + 1)
        for k in range(m + 1):
            low = k - limit
            if low <= 0:
                dp_curr[k] = prefix[k]
            else:
                dp_curr[k] = (prefix[k] - prefix[low - 1]) % mod
        dp_prev = dp_curr
    return dp_prev[m] % mod

